Console.WriteLine("=== BUILD ERRORS ===");
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"[ERROR] Project: {GetProject(e)} | Code: {e.Code} | File: {e.File}({e.LineNumber}) | {e.Text}");
});

Console.WriteLine("\n=== BUILD WARNINGS ===");
build.VisitAllChildren<Warning>(w => {
    Console.WriteLine($"[WARN] Project: {GetProject(w)} | Code: {w.Code} | File: {w.File}({w.LineNumber}) | {w.Text}");
});

static string GetProject(BaseNode node) {
    var current = node;
    while (current != null) {
        if (current is Project p) return p.Name;
        current = current.Parent as BaseNode;
    }
    return "unknown";
}
