using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check which projects have errors
Console.WriteLine("=== PROJECTS WITH ERRORS ===");
build.VisitAllChildren<Project>(p => {
    bool hasErrors = false;
    p.VisitAllChildren<Error>(e => hasErrors = true);
    Console.WriteLine($"  {p.Name} -> HasErrors={hasErrors}");
});

// Check Api project - did it also fail?
Console.WriteLine("\n=== ALL ERRORS INCLUDING MSB ===");
build.VisitAllChildren<AbstractDiagnostic>(d => {
    if (d is Error err) {
        var proj = err.GetNearestParent<Project>();
        Console.WriteLine($"  [{proj?.Name ?? "solution"}] {err.Code}: {err.Text}");
    }
});
EOF
