using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find the build phase projects (not restore)
Console.WriteLine("=== BUILD PHASE PROJECTS ===");
int i = 0;
build.VisitAllChildren<Project>(p => {
    i++;
    bool hasErrors = false;
    p.VisitAllChildren<Error>(e => hasErrors = true);
    // Check if CoreCompile target ran
    bool compiled = false;
    p.VisitAllChildren<Target>(t => { if (t.Name == "CoreCompile") compiled = true; });
    if (hasErrors || !compiled)
        Console.WriteLine($"  #{i} {p.Name} | HasErrors={hasErrors} | Compiled={compiled}");
});
EOF
